import sqlite3
p='/app/main.db'
for uri in [p, f'file:{p}?immutable=1']:
 try:
  c=sqlite3.connect(uri, uri=uri.startswith('file:'))
  print(uri, c.execute('pragma journal_mode').fetchone(), c.execute('pragma integrity_check').fetchone())
  print(c.execute("select name,sql from sqlite_master").fetchall())
  for row in c.execute('select * from items order by id') if c.execute("select count(*) from sqlite_master where name='items'").fetchone()[0] else []: print(row)
 except Exception as e: print(type(e).__name__,e)
PY

